			title = "The Doomed Fleet",
			hint = "Loosen the old sailor's tongue with a flagon of mead.",
			unlock = {
				{ type = "quest", id = 288 },
			},
			text = [=[With a fresh drink in hand, Fitzsimmons tells it plainly. The fleet sailed; the dragons came; the ships burned and went down. He does not know why he lived. He curses his captain for leading them to their doom, and he drinks to his brothers in their watery graves.]=],
