			title = "The Cursed Eye",
			hint = "Open the strongbox of the Intrepid.",
			unlock = {
				{ type = "quest", id = 290 },
			},
			text = [=[{link:captain-halyndor}Captain Halyndor{/link} had kept the thing locked in his strongbox aboard the {i}Intrepid{/i}. When the box was opened, it held a blackened orb that pulsed with a sickly light: an Eye of Paleth, fouled by the sorrow it had witnessed. Fitzsimmons would not touch it. He sent it to the priest {link:glorin-steelbrow}Glorin Steelbrow{/link}.]=],
