	sections = {
		{
			title = "Summary",
			text = [=[Sida lives in {link:menethil-harbor}Menethil Harbor{/link}. Once a week she walks all the way to {link:ironbeard-s-tomb}Ironbeard's Tomb{/link}, near {link:dun-modr}Dun Modr{/link}, through a land at war. On her last visit, the oozes of the tomb came for her. In her panic she threw her bag at one of them, and the ooze swallowed it whole. She got away, but the bag held something she very much needed.]=],
