Add({
	kind = "figure",
	id = "chieftain-nek-rosh",
	title = "Chieftain Nek'rosh",
	aliases = { "Nek'rosh" },
	subtitle = "Chieftain of the Dragonmaw",
	tier = "B",
	region = "wetlands",
	npc = { 2091 },
	allegiance = "Dragonmaw Clan",
	found = "Angerfang Encampment",
	pin = { x = 53.5, y = 54.7 },
	unlock = {
		{ type = "target" },
	},
	hint = [=[Face the chieftain who leads the Dragonmaw from their camp in the eastern hills.]=],
	sections = {
		{
			title = "Summary",
			text = [=[Nek'rosh is the chieftain of the {link:dragonmaw-clan}Dragonmaw Clan{/link} in the {link:wetlands}Wetlands{/link}. He is the son of Nekros, who led the clan in the years when it held the red dragons captive. Nekros bent the dragons to his will with powerful magic. When the magic failed, the dragons turned on their masters, and Nekros was killed. His son has sworn revenge on the dragons who slew him.]=],
		},
		{
			title = "Significance",
			text = [=[Under Nek'rosh, a broken clan has become an army again. The Dragonmaw have pushed into {link:dun-algaz}Dun Algaz{/link}, built siege engines and turned their eyes on {link:menethil-harbor}Menethil Harbor{/link}.]=],
		},
		{
			title = "Deeds",
			text = [=[• He gathered the scattered Dragonmaw at {link:angerfang-encampment}Angerfang Encampment{/link}.
• He drove his warriors into {link:dun-algaz}Dun Algaz{/link}, cutting the road between Menethil and {link:loch-modan}Loch Modan{/link}.
• He built catapults to lay siege to {link:menethil-harbor}Menethil Harbor{/link}.]=],
		},
		{
			title = "Unrecorded",
			text = [=[The chronicles of the {link:second-war}Second War{/link} tell of the Dragonmaw who held the Dragon Queen at {link:grim-batol}Grim Batol{/link}. What part Nek'rosh himself played in those years, they do not say.]=],
		},
	},
	chapters = {
