			hint = [=[Carry the Dragonmaw's war banners to the captain in Menethil Keep.]=],
			unlock = {
				{ type = "quest", id = 464 },
			},
			text = [=[When the banners were laid before him, {link:captain-stoutfist}Captain Stoutfist{/link} told what the dwarves knew of their foe. The Dragonmaw were no longer what they had been when they rode dragons. Their chieftain was the son of the {link:orcs}orc{/link} who had once enslaved the red flight, and he had not forgotten how his father died.]=],
		},
		{
			key = "defeat-nek-rosh",
			title = "Defeat Nek'rosh",
			hint = "Burn the catapults and strike down the chieftain.",
			unlock = {
				{ type = "quest", id = 474 },
			},
			text = [=[The catapults burned first, and Menethil was safe from them. Then Nek'rosh fell in his own camp. {link:captain-stoutfist}Stoutfist{/link} judged it a telling blow, one from which the clan might never recover.]=],
