Add({
	kind = "topic",
	id = "dragonmaw-clan",
	title = "Dragonmaw Clan",
	aliases = { "Dragonmaw clan", "Dragonmaw orcs" },
	category = "group",
	region = "wetlands",
	unlock = {
		{ type = "read" },
		{ type = "quest", id = 464 },
	},
	sections = {
		{
			title = "Summary",
			text = [=[The Dragonmaw are a clan of {link:orcs}orcs{/link} of the old {link:horde}Horde{/link}. In the {link:second-war}Second War{/link} they did what no other clan could: they made the red dragons their servants. From their stronghold at {link:grim-batol}Grim Batol{/link} they held {link:alexstrasza}Alexstrasza{/link}, the Dragon Queen, captive by the power of an artifact that {link:deathwing}Deathwing{/link} had forged, and they raised her young as mounts of war. Red dragons ridden by Dragonmaw orcs burned the ships of the {link:alliance}Alliance{/link} at sea.]=],
		},
		{
			title = "The Fall",
			text = [=[The magic that bound the dragons failed. The red flight turned on the clan and hunted it without mercy. Nekros, who had led the Dragonmaw, was slain, and the clan was all but destroyed. The few who lived fled {link:grim-batol}Grim Batol{/link} and hid in the mountains east of the {link:wetlands}Wetlands{/link} road.]=],
		},
		{
			title = "In These Days",
			text = [=[The Dragonmaw have grown strong again under {link:chieftain-nek-rosh}Chieftain Nek'rosh{/link}, son of Nekros. From {link:angerfang-encampment}Angerfang Encampment{/link} and the hidden {link:dragonmaw-retreat}Dragonmaw Retreat{/link} they strike west, and they have seized the pass of {link:dun-algaz}Dun Algaz{/link}. They build catapults, gather weapons and, it is whispered, still dream of dragons. The dwarves of Menethil call them fierce, but they know the clan without its dragons is a lesser threat than the clan that once darkened the sky.]=],
		},
	},
})

